import {OFFERS,COMPANY,DEMO_DATE} from './data.js';
import {money,number,percent,calculate,validateNeed,parseNeeds,matchNeed} from './domain.js';
import {loadState,saveState,event as addEvent} from './store.js';
import {icon,product,logo} from './icons.js';
import {enter,exitLayer} from './motion.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=(s,year=false)=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',...(year?{year:'numeric'}:{})}).format(new Date(s+'T12:00:00'));
const plural=(n,forms)=>forms[n%100>=11&&n%100<=14?2:n%10===1?0:n%10>=2&&n%10<=4?1:2];
let state=loadState(),view='offers',category='Все',query='',sort='saving',orderFilter='all',dialog=null,detailTab='terms',toastTimer,lastFocus,renderedView=null,selectedOfferId=null,quoteQuantity=1,quoteValid=true,scope='all',layoutStarted=false,layoutFrame=0,cardObserver=null;
const el=$('#app'),overlay=$('#overlay-root');
const SECTIONS=[['offers','Предложения','grid'],['orders','Мои закупки','bag'],['needs','Потребности','file'],['analytics','Аналитика','chart']];
const totals=()=>OFFERS.reduce((a,o)=>{const c=calculate(o);return {saving:a.saving+c.saving,standalone:a.standalone+c.standaloneTotal,group:a.group+c.groupTotal};},{saving:0,standalone:0,group:0});
const activeOrders=()=>state.orders.filter(o=>o.status!=='cancelled');
const save=()=>{if(!saveState(state))toast('Изменения доступны только до закрытия страницы');};
const offerById=id=>OFFERS.find(o=>o.id===id);
const orderFor=id=>activeOrders().find(o=>o.offerId===id);
function button(text,action,cls='secondary',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function render(){
 if(renderedView!==view)cardObserver?.disconnect();
 if(!$('.shell'))el.innerHTML=shellView();
 updateShell();
 const headings={orders:['Мои закупки','Все ваши заявки и согласованные условия в одном месте.'],needs:['Потребности бизнеса','Укажите нужные товары. Оптима найдёт совместимые предложения.'],analytics:['Экономика закупок','Посмотрите, как объединение объёма меняет стоимость вашего заказа.']};
 const actions=view==='analytics'?button(icon('download','sm')+'Выгрузить расчёт','export','secondary','aria-label="Выгрузить расчёт"'):view==='orders'?button(icon('plus','sm')+'Выбрать закупку','go-offers','primary','aria-label="Выбрать закупку"'):button(icon('upload','sm')+'Загрузить список','upload','secondary','aria-label="Загрузить список закупок"')+button(icon('plus','sm')+'Добавить потребность','new-need','primary','aria-label="Добавить потребность"');
 $('#scene').innerHTML=`${view==='offers'?'':`<header class="page-header"><div><span class="eyebrow">ОПТИМА / ДЛЯ БИЗНЕСА</span><h1>${headings[view][0]}</h1><p>${headings[view][1]}</p></div><div class="page-actions">${actions}</div></header>`}<div id="view-content" data-section="${view}">${view==='offers'?offersView():view==='orders'?ordersView():view==='needs'?needsView():analyticsView()}</div><footer class="footer"><div class="footer-brand">Оптима<span>Совместные закупки для бизнеса</span></div><p class="data-note">Демонстрационный прототип.<br>Компании, цены и условия вымышлены.</p><div class="footer-links"><button data-action="help">Как работает сервис${icon('arrow','sm')}</button><button data-action="privacy">Данные и условия${icon('arrow','sm')}</button></div></footer>`;
 fitQuotePanel();startLayoutTracking();
 if(renderedView!==view){enter($('#scene'),8,320);if(view==='offers')enterCards();}
 renderedView=view;
 document.title=`${SECTIONS.find(([id])=>id===view)[1]} · Оптима · ВТБ`;
 if(location.hash!==`#${view}`)history.replaceState(null,'',`#${view}`);
}

function shellView(){
 return `<div class="shell"><header class="topbar"><div class="header-inner"><a href="#offers" class="brand" aria-label="ВТБ Оптима — предложения">${logo}<span class="brand-divider"></span><strong>Оптима</strong></a><nav class="main-nav" aria-label="Разделы сервиса"><i class="nav-marker" aria-hidden="true"></i>${SECTIONS.map(([id,label])=>`<button class="nav-item" data-action="view" data-view="${id}" aria-label="${label}"><span>${label}</span><small class="nav-count" data-nav-count="${id}"></small></button>`).join('')}</nav><div class="topbar-right"><span class="service-status">Демо</span><button class="company-pill" data-action="company" aria-label="Данные компании ${esc(COMPANY.name)}"><span class="company-avatar">С</span><span>${esc(COMPANY.name)}</span>${icon('down','sm')}</button><button class="icon-button notification-button" data-action="notifications" aria-label="Уведомления" data-tooltip="Уведомления">${icon('bell')}</button><button class="profile-btn" data-action="profile" aria-label="Профиль Александра Соколова" data-tooltip="Профиль"><span class="user-avatar">АС</span></button></div></div></header><div class="main-shell"><main id="main" class="content" tabindex="-1"><div id="scene"></div></main><nav class="tabs" aria-label="Разделы Оптимы"><i class="tab-marker" aria-hidden="true"></i>${SECTIONS.map(([id,label,symbol])=>`<button class="tab" data-action="view" data-view="${id}">${icon(symbol)}<span>${label}</span></button>`).join('')}</nav></div></div>`;
}

function updateShell(){
 const index=SECTIONS.findIndex(([id])=>id===view),counts={offers:OFFERS.length,orders:activeOrders().length,needs:state.needs.length};
 for(const nav of document.querySelectorAll('.main-nav,.tabs'))nav.style.setProperty('--active-index',index);
 for(const b of document.querySelectorAll('.main-nav [data-view],.tabs [data-view]')){const active=b.dataset.view===view;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}
 for(const n of document.querySelectorAll('[data-nav-count]')){const count=counts[n.dataset.navCount];n.textContent=count??'';n.hidden=count===undefined||count===0;}
 $('.notification-button')?.classList.toggle('notice-dot',!state.notificationsRead);
}
function matchedIds(){return new Set(state.needs.map(n=>matchNeed(n,OFFERS)?.id).filter(Boolean));}
function ensureSelection(items=filtered()){
 if(!items.length){selectedOfferId=null;return;}
 if(!items.some(o=>o.id===selectedOfferId)){selectedOfferId=items[0].id;quoteQuantity=orderFor(selectedOfferId)?.quantity||items[0].quantity;quoteValid=true;}
}
function scopeButtons(){const matched=matchedIds();return [['all','Все предложения',OFFERS.length],['matched','По потребностям',matched.size],['favorites','Избранное',state.favorites.length]].map(([id,label,count])=>`<button class="scope-tab ${scope===id?'active':''}" data-action="scope" data-scope="${id}" aria-pressed="${scope===id}">${label}<span data-scope-count="${id}">${count}</span></button>`).join('');}


function offersView(){
 ensureSelection();const layout=state.ui?.catalogLayout==='list'?'list':'grid';
 return `${heroView()}<section class="opportunities" id="catalog-start" aria-labelledby="catalog-title"><div class="section-heading"><div><span class="eyebrow">ВОЗМОЖНОСТИ ДЛЯ ВАШЕГО БИЗНЕСА</span><h2 id="catalog-title">Найдите свою закупку<span id="offers-count" class="result-count" aria-live="polite">${filtered().length}</span></h2></div><div class="page-actions">${button(icon('upload','sm')+'Загрузить список','upload','secondary','aria-label="Загрузить список закупок"')}${button(icon('plus','sm')+'Добавить потребность','new-need','primary','aria-label="Добавить потребность"')}</div></div><div class="procurement-workspace"><div class="catalog"><div class="catalog-heading"><div id="scope-tabs" class="scope-tabs" role="group" aria-label="Подборка предложений">${scopeButtons()}</div><div class="catalog-mode" role="group" aria-label="Вид предложений">${[['grid','Карточки','grid'],['list','Список','menu']].map(([id,label,symbol])=>`<button class="${layout===id?'active':''}" data-action="catalog-layout" data-layout="${id}" aria-label="${label}" aria-pressed="${layout===id}" data-tooltip="${label}">${icon(symbol,'sm')}</button>`).join('')}</div></div><div class="catalog-tools"><label class="search">${icon('search','sm')}<input id="offer-search" type="search" placeholder="Найдите товар или поставщика" aria-label="Найти товар" value="${esc(query)}"><kbd aria-hidden="true">/</kbd></label><label class="select-wrap"><span class="sr-only">Категория товаров</span><select id="category" aria-label="Категория товаров">${['Все','Упаковка','Для офиса','Хозтовары'].map(c=>`<option ${category===c?'selected':''} value="${c}">${c==='Все'?'Все категории':c}</option>`).join('')}</select>${icon('down','sm')}</label><label class="sort-wrap">${icon('sort','sm')}<select id="sort" aria-label="Сортировка"><option value="saving" ${sort==='saving'?'selected':''}>По выгоде</option><option value="deadline" ${sort==='deadline'?'selected':''}>По сроку сбора</option><option value="ready" ${sort==='ready'?'selected':''}>По готовности</option></select></label></div><div id="offers-grid" class="offers-list" data-layout="${layout}">${offerCards()}</div><div class="catalog-bottom"><span>${icon('info','sm')}В стоимость включена доставка для указанного объёма.</span><button class="text-button" data-action="new-need">Не нашли свой товар?${icon('plus','sm')}</button></div></div><aside class="quote-panel" id="purchase-preview" data-offer-id="${selectedOfferId||''}" aria-label="Расчёт выбранной закупки">${quoteView()}</aside></div></section>`;
}

function heroView(){
 const o=OFFERS[0],c=calculate(o);
 return `<section class="service-hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="hero-eyebrow"><span></span>СОВМЕСТНЫЕ ЗАКУПКИ ДЛЯ БИЗНЕСА</div><h1 id="hero-title">Оптовая цена.<br><span>Без лишних<br class="hero-mobile-break"> закупок.</span></h1><p>Объединяйте спрос с другими компаниями.<br>Покупайте ровно столько, сколько нужно вам.</p><div class="hero-actions"><button class="hero-cta" data-action="browse-offers">Выбрать закупку<span>${icon('arrow')}</span></button><button class="hero-about" data-action="help">Как это работает${icon('arrow','sm')}</button></div><div class="hero-assurance">${icon('shield','sm')}Ваш заказ, документы и платёж остаются отдельными</div></div><div class="hero-visual"><span class="hero-word" aria-hidden="true">ВМЕСТЕ</span><img class="hero-object" src="assets/optima-procurement-hero.png" width="1254" height="1254" alt="" fetchpriority="high" decoding="async"><div class="hero-example"><span class="hero-example-icon">${icon('users')}</span><div><small>Объём группы в примере</small><strong>${number(c.totalQuantity)} ${o.unit}</strong></div><span class="hero-example-own">Один заказ<br><strong>${number(o.quantity)} ${o.unit}</strong></span></div><div class="hero-saving"><strong>−${percent(c.savingPercent)}</strong><span>На заказе ${number(o.quantity)}<br>курьерских пакетов</span></div></div></section>`;
}

function enterCards(){
 cardObserver?.disconnect();
 if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;
 const animate=(card,index=0)=>{
  if(typeof card.animate!=='function')return;
  const animation=card.animate([{opacity:0,transform:'translateY(15px)'},{opacity:1,transform:'translateY(0)'}],{duration:420,delay:Math.min(index,2)*55,fill:'backwards',easing:'cubic-bezier(.05,.6,.2,1)'});
  animation.finished.catch(()=>{});
 };
 const cards=[...document.querySelectorAll('.offer-card')];
 if(typeof window.IntersectionObserver==='function'){
  cardObserver=new window.IntersectionObserver(entries=>{let index=0;for(const entry of entries){if(!entry.isIntersecting)continue;animate(entry.target,index++);cardObserver.unobserve(entry.target);}},{threshold:.08});
  cards.forEach(card=>cardObserver.observe(card));
 }else cards.forEach(animate);
}

function filtered(){const matched=matchedIds();let items=OFFERS.filter(o=>(category==='Все'||category===o.category)&&(scope==='all'||scope==='matched'&&matched.has(o.id)||scope==='favorites'&&state.favorites.includes(o.id))&&(`${o.name} ${o.spec} ${o.supplier}`).toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru')));items.sort((a,b)=>sort==='deadline'?a.deadline.localeCompare(b.deadline):sort==='ready'?Number(calculate(b).ready)-Number(calculate(a).ready):calculate(b).savingPercent-calculate(a).savingPercent);return items;}

function offerCards(){
 const offers=filtered(),matched=matchedIds();
 return offers.length?offers.map(o=>{
  const c=calculate(o),selected=selectedOfferId===o.id,joined=orderFor(o.id);
  return `<article class="offer-card opportunity-row ${selected?'selected':''}">
   <button class="proposal-select" data-action="select-offer" data-id="${o.id}" aria-pressed="${selected}" aria-label="Рассчитать закупку: ${o.name}. Стоимость ${money(c.groupTotal)} за ${number(o.quantity)} ${o.unit}, с доставкой. Экономия ${money(c.saving)}.">
    <span class="proposal-media" style="--product-tone:${o.accent}">${product(o.kind)}${joined?`<span class="product-tag joined">${icon('check','sm')}Вы участвуете</span>`:matched.has(o.id)?`<span class="product-tag">${icon('file','sm')}По вашей потребности</span>`:''}</span>
    <span class="proposal-copy"><span class="product-category">${o.category}</span><strong class="offer-title">${o.name}</strong><span class="offer-spec">${o.spec}</span><span class="offer-supplier"><i class="supplier-initial">${o.supplierInitial}</i>${o.supplier}</span></span>
    <span class="proposal-cost"><strong class="offer-price amount">${money(c.groupTotal)}</strong><span class="old-price amount">${money(c.standaloneTotal)}</span><span class="row-saving amount">Экономия ${money(c.saving)}</span><span class="cost-caption">За ${number(o.quantity)} ${o.unit} · С доставкой</span></span>
    <span class="proposal-group"><span class="row-group-label ${c.ready?'is-ready':''}"><span>${icon('users','sm')}${o.participants+1} ${plural(o.participants+1,['компания','компании','компаний'])} с вами</span><strong>${c.ready?'Объём набран':Math.round(c.progress)+'% объёма'}</strong></span><span class="progress ${c.ready?'ready':''}" role="progressbar" aria-label="Объём группы" aria-valuenow="${Math.round(c.progress)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${c.progress}%"></i></span><span class="row-deadline">Сбор до ${date(o.deadline)}</span></span>
    <span class="proposal-cta">${selected?'Выбрано для расчёта':'Рассчитать свой объём'}${icon(selected?'check':'arrow','sm')}</span>
   </button>
   <button class="icon-button favorite ${state.favorites.includes(o.id)?'active':''}" data-action="favorite" data-id="${o.id}" aria-label="${state.favorites.includes(o.id)?'Убрать из избранного':'В избранное'}: ${o.name}" aria-pressed="${state.favorites.includes(o.id)}">${icon('heart','sm')}</button>
  </article>`;
 }).join(''):`<div class="empty catalog-empty"><div class="empty-icon">${icon(scope==='favorites'?'heart':'search')}</div><h3>${scope==='favorites'?'Сохраните интересные предложения':'Совпадений пока нет'}</h3><p>${scope==='favorites'?'Нажмите на сердечко у закупки, чтобы вернуться к ней позже.':'Попробуйте другую категорию или добавьте товар, который нужен бизнесу.'}</p>${button('Сбросить фильтры','clear-filter','secondary')}</div>`;
}

function quoteView(){
 const o=offerById(selectedOfferId);
 if(!o)return `<div class="quote-placeholder"><span>${icon('box')}</span><h2>Рассчитайте свой заказ</h2><p>Выберите предложение, чтобы указать объём и сравнить полную стоимость.</p>${button('Добавить потребность','new-need','secondary')}</div>`;
 const joined=orderFor(o.id);if(joined){quoteQuantity=joined.quantity;quoteValid=true;}
 const c=joined?.calculation||calculate(o,quoteQuantity);
 return `<div class="quote-scroll">
  <div class="quote-heading"><span class="quote-eyebrow">Ваш расчёт</span><span class="quote-live"><i></i>С доставкой</span></div>
  <div class="quote-product"><div class="product-visual">${product(o.kind)}</div><div><h2>${o.name}</h2><p>${o.spec}</p><span>${o.supplier}</span></div></div>
  <div class="quote-quantity-heading"><label for="quote-quantity">Сколько нужно вашей компании</label><span>${o.unit}</span></div>
  <div class="quote-quantity"><div class="quantity-control"><button data-action="quote-minus" aria-label="Уменьшить объём расчёта" ${joined?'disabled':''}>${icon('minus','sm')}</button><input id="quote-quantity" type="number" min="1" max="1000000" step="${o.step}" value="${quoteQuantity}" aria-label="Объём для расчёта" aria-describedby="quote-error" ${joined?'disabled':''}><button data-action="quote-plus" aria-label="Увеличить объём расчёта" ${joined?'disabled':''}>${icon('plus','sm')}</button></div><span>Шаг ${number(o.step)} ${o.unit}</span></div>
  <p id="quote-error" class="quote-error" hidden>Укажите целое число от 1 до 1 000 000.</p>
  <div class="quote-price-hero"><span>Стоимость вашего заказа</span><strong class="amount" id="quote-total">${money(c.groupTotal)}</strong><div><span id="quote-volume">${number(quoteQuantity)} ${o.unit}</span><span class="quote-discount" id="quote-discount">−${percent(c.savingPercent)}</span></div></div>
  <div class="quote-comparison"><div><span>При отдельной закупке</span><strong class="amount" id="quote-standalone">${money(c.standaloneTotal)}</strong></div><div><span>Товар по общей цене</span><strong class="amount" id="quote-goods">${money(c.groupGoods)}</strong></div><div><span>Доставка вашей компании</span><strong class="amount">${money(o.groupDelivery)}</strong></div></div>
  <div class="quote-benefit" id="quote-benefit"><span>${icon('chart','sm')}Ваша экономия</span><strong class="amount" id="quote-saving">${money(c.saving)}</strong></div>
  <div class="quote-group"><div><span>${icon('users','sm')}${o.participants+1} ${plural(o.participants+1,['компания','компании','компаний'])} с вами</span><strong id="quote-progress-label">${Math.round(c.progress)}%</strong></div><div class="progress ${c.ready?'ready':''}" id="quote-progress" role="progressbar" aria-label="Объём выбранной группы" aria-valuenow="${Math.round(c.progress)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${c.progress}%"></i></div><p id="quote-group-status">${c.ready?'Объём набран с учётом вашего заказа.':'До оптового объёма: '+number(c.missing)+' '+o.unit}</p><span class="quote-deadline">${icon('clock','sm')}Сбор до ${date(o.deadline)}</span></div>
  <p id="quote-announcement" class="sr-only" role="status" aria-live="polite"></p>
 </div><div class="quote-footer">${button((joined?'Открыть мою заявку':'Перейти к условиям')+icon('arrow','sm'),joined?'open-existing':'quote-open','primary full',`data-id="${o.id}"`)}<p>${icon('shield','sm')}Отдельный заказ, документы и платёж</p></div>`;
}

function selectOffer(id){
 const o=offerById(id);if(!o)return;
 const changed=selectedOfferId!==id;
 if(changed){selectedOfferId=id;quoteQuantity=orderFor(id)?.quantity||o.quantity;quoteValid=true;}
 for(const b of document.querySelectorAll('[data-action="select-offer"]')){const active=b.dataset.id===id;b.setAttribute('aria-pressed',String(active));b.closest('.opportunity-row').classList.toggle('selected',active);b.querySelector('.proposal-cta').innerHTML=(active?'Выбрано для расчёта':'Рассчитать свой объём')+icon(active?'check':'arrow','sm');}
 const panel=$('#purchase-preview');if(changed){panel.innerHTML=quoteView();panel.dataset.offerId=id;fitQuotePanel();}
 if(window.matchMedia?.('(max-width:1179px)').matches)openOffer(id,quoteQuantity);
 else if(changed)enter($('#purchase-preview .quote-scroll'),6,200);
}
function fitQuotePanel(){
 const panel=$('#purchase-preview');if(!panel||window.innerWidth<1180)return;
 const height=Math.max(280,Math.floor(window.innerHeight-128));
 if(panel.style.maxHeight!==height+'px')panel.style.maxHeight=height+'px';
}

function startLayoutTracking(){
 if(layoutStarted)return;layoutStarted=true;
 const schedule=()=>{if(layoutFrame)return;layoutFrame=window.requestAnimationFrame(()=>{layoutFrame=0;fitQuotePanel();});};
 window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);
 if(window.ResizeObserver)new window.ResizeObserver(schedule).observe($('#scene'));
 document.fonts?.ready.then(schedule);
}

function updateQuoteQuantity(value){
 const o=offerById(selectedOfferId);if(!o||orderFor(o.id))return;
 const input=$('#quote-quantity');quoteValid=value!==''&&Number.isInteger(Number(value))&&Number(value)>0&&Number(value)<=1000000;
 input?.classList.toggle('invalid',!quoteValid);input?.setAttribute('aria-invalid',String(!quoteValid));$('#quote-error').hidden=quoteValid;
 const action=$('[data-action="quote-open"]');if(action)action.disabled=!quoteValid;
 if(!quoteValid)return;
 quoteQuantity=Number(value);if(input)input.value=quoteQuantity;
 const c=calculate(o,quoteQuantity),fields={'quote-total':money(c.groupTotal),'quote-volume':number(quoteQuantity)+' '+o.unit,'quote-discount':'−'+percent(c.savingPercent),'quote-standalone':money(c.standaloneTotal),'quote-goods':money(c.groupGoods),'quote-saving':money(c.saving),'quote-progress-label':Math.round(c.progress)+'%','quote-group-status':c.ready?'Объём набран с учётом вашего заказа.':'До оптового объёма: '+number(c.missing)+' '+o.unit};
 for(const [id,text] of Object.entries(fields))if($('#'+id))$('#'+id).textContent=text;
 $('#quote-progress').setAttribute('aria-valuenow',String(Math.round(c.progress)));$('#quote-progress i').style.width=c.progress+'%';$('#quote-progress').classList.toggle('ready',c.ready);
 if(action)action.disabled=!c.beneficial;
 $('#quote-announcement').textContent=`Стоимость ${money(c.groupTotal)}. Экономия ${money(c.saving)}.`;
}

function ordersView(){
 const orders=state.orders.filter(o=>orderFilter==='all'||(orderFilter==='active'?o.status!=='cancelled':o.status==='cancelled'));
 return `<div class="chips status-filters mb20">${[['all','Все'],['active','Активные'],['cancelled','Отменённые']].map(([id,label])=>`<button class="chip ${orderFilter===id?'active':''}" data-action="order-filter" data-filter="${id}" aria-pressed="${orderFilter===id}">${label}</button>`).join('')}</div>${orders.length?orders.map(order=>{const o=offerById(order.offerId);return `<article class="order-card"><div class="order-art" style="--visual:${o.accent}">${product(o.kind)}</div><div class="order-info"><div class="badges-line"><span class="status ${order.status==='cancelled'?'gray':order.status==='ready'?'green':'blue'}">${statusLabel(order)}</span><small>${order.number}</small></div><h3>${o.name}</h3><p class="order-meta">${number(order.quantity)} ${o.unit} · ${o.supplier}</p></div><div class="order-price"><strong class="amount">${money(order.calculation.groupTotal)}</strong><small class="${order.status==='cancelled'?'cancelled':''}">${order.status==='cancelled'?'Заявка отменена':'Ожидаемая экономия '+money(order.calculation.saving)}</small></div><div class="order-action">${button('Открыть условия'+icon('arrow','sm'),'order-detail','secondary',`data-id="${order.id}"`)}</div></article>`;}).join(''):`<section class="orders-empty"><div class="orders-empty-copy"><span class="eyebrow">${orderFilter==='cancelled'?'ВСЁ В ПОРЯДКЕ':'НОВЫЕ ВОЗМОЖНОСТИ ДЛЯ БИЗНЕСА'}</span><h2>${orderFilter==='cancelled'?'Отменённых заявок нет':'Начните с первой закупки'}</h2><p>Выберите предложение, рассчитайте свой объём и подтвердите условия. Здесь появятся ваши заявки.</p>${button('К предложениям'+icon('arrow','sm'),'go-offers','primary')}</div><img src="assets/optima-procurement-hero.png" width="1254" height="1254" alt="" loading="lazy"></section>`}`;
}

function statusLabel(o){return o.status==='cancelled'?'Отменена':o.status==='ready'?'Объём группы набран':'Сбор группы';}
function needsView(){
 return `${state.needs.length?`<section class="panel needs-panel"><div class="needs-summary"><div><span class="summary-count">${state.needs.length}</span><strong>Позиций в списке</strong></div><span>${icon('check','sm')}Подобраны предложения: ${state.needs.filter(n=>matchNeed(n,OFFERS)).length}</span></div><div class="table-wrap"><table class="data-table"><caption class="sr-only">Закупочные потребности вашей компании</caption><thead><tr><th>Товар и характеристики</th><th>Количество</th><th>Нужен до</th><th>Предложение</th><th><span class="sr-only">Удалить</span></th></tr></thead><tbody>${state.needs.map(n=>{const o=matchNeed(n,OFFERS);return `<tr><td><div class="need-product"><span class="need-art" style="--visual:${o?.accent||'#eef3fb'}">${o?product(o.kind):icon('box')}</span><div><div class="cell-main">${esc(n.name)}</div><div class="cell-sub">${esc(n.spec)}</div></div></div></td><td class="amount">${number(n.quantity)} ${esc(n.unit)}</td><td>${date(n.deadline)}</td><td>${o?`<button class="text-button" data-action="offer" data-id="${o.id}" data-quantity="${n.quantity}" data-price="${n.price}">Смотреть${icon('arrow','sm')}</button>`:`<span class="status gray">Ищем совпадение</span>`}</td><td><button class="icon-button" data-action="delete-need" data-id="${esc(n.id)}" aria-label="Удалить потребность ${esc(n.name)}">${icon('close','sm')}</button></td></tr>`;}).join('')}</tbody></table></div></section>`:`<div class="empty"><div class="empty-icon">${icon('file')}</div><h3>Что нужно вашему бизнесу?</h3><p>Добавьте товар и срок, чтобы найти подходящее предложение общей закупки.</p>${button('Добавить потребность','new-need','primary')}</div>`}<section class="import-banner"><span class="banner-icon">${icon('upload')}</span><div><h2>Ваш список уже готов?</h2><p>Загрузите позиции из учётной системы в CSV или JSON.<br>Оптима подберёт совместимые предложения.</p></div>${button('Загрузить список'+icon('arrow','sm'),'upload','secondary')}</section>`;
}

function analyticsView(){
 const expected=activeOrders().reduce((a,o)=>a+o.calculation.saving,0),t=totals(),values=OFFERS.map(o=>calculate(o).saving),max=Math.max(...values);
 const categories=['Упаковка','Для офиса','Хозтовары'].map((name,i)=>({name,color:['#0062ff','#689bff','#b9d1ff'][i],value:OFFERS.filter(o=>o.category===name).reduce((a,o)=>a+calculate(o).saving,0)}));
 let offset=0;const circumference=2*Math.PI*72;
 const arcs=categories.map(c=>{const length=c.value/t.saving*circumference;const arc=`<circle cx="90" cy="90" r="72" fill="none" stroke="${c.color}" stroke-width="22" stroke-dasharray="${length} ${circumference-length}" stroke-dashoffset="${-offset}"/>`;offset+=length;return arc;}).join('');
 return `<section class="economy-overview" aria-label="Экономика подборки"><div class="economy-main"><span class="eyebrow">ПОТЕНЦИАЛ ВАШЕЙ ПОДБОРКИ</span><span class="economy-label">Возможная экономия</span><strong class="amount">${money(t.saving)}</strong><p>Для объёмов в предложениях, с учётом доставки</p></div><div class="economy-comparison"><div><span>Самостоятельно</span><strong class="amount">${money(t.standalone)}</strong></div><span class="economy-arrow">${icon('arrow')}</span><div><span>В общих закупках</span><strong class="amount">${money(t.group)}</strong></div><span class="saving">−${percent(t.saving/t.standalone*100)}</span></div></section><div class="analytics-grid"><section class="panel chart-card"><div class="chart-header"><div><span class="eyebrow">СРАВНЕНИЕ ПОЗИЦИЙ</span><h2>Где больше выгода</h2></div><span>С доставкой</span></div><div class="horizontal-chart" role="img" aria-label="Возможная экономия для каждого товара">${OFFERS.map((o,i)=>`<div class="chart-column horizontal-row"><span>${o.name}</span><div class="horizontal-track"><i class="${values[i]===max?'highest':''}" style="width:${values[i]/max*100}%"></i></div><strong class="amount">${money(values[i])}</strong></div>`).join('')}</div><p class="analytics-note">Оптовые условия действуют при наборе необходимого объёма. Это расчёт возможной экономии, а не результат совершённых сделок.</p></section><section class="panel chart-card category-card"><div class="chart-header"><div><span class="eyebrow">СТРУКТУРА ЭКОНОМИИ</span><h2>По категориям</h2></div><span>${OFFERS.length} предложений</span></div><div class="category-breakdown"><div class="category-donut"><svg viewBox="0 0 180 180" role="img" aria-label="${categories.map(c=>c.name+': '+money(c.value)).join('. ')}"><g transform="rotate(-90 90 90)">${arcs}</g></svg><div><strong>3</strong><span>категории</span></div></div><div class="category-legend">${categories.map(c=>`<div><span><i style="background:${c.color}"></i>${c.name}</span><strong class="amount">${money(c.value)}</strong></div>`).join('')}</div></div><div class="analytics-expected"><span>По активным заявкам ожидается</span><strong class="amount">${money(expected)}</strong><small>Фактическая экономия появится после исполнения закупок.</small></div></section></div><section class="panel comparison-panel"><div class="panel-heading"><div><span class="eyebrow">ПРОЗРАЧНЫЙ РАСЧЁТ</span><h2>Из чего складывается выгода</h2></div><span>Для объёмов в предложениях</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Товар / объём</th><th>Самостоятельно</th><th>В общей закупке</th><th>Экономия</th></tr></thead><tbody>${OFFERS.map(o=>{const c=calculate(o);return `<tr><td><div class="cell-main">${o.name}</div><div class="cell-sub">${number(o.quantity)} ${o.unit}</div></td><td>${money(c.standaloneTotal)}</td><td><strong>${money(c.groupTotal)}</strong></td><td class="positive-text">${money(c.saving)}<span class="cell-sub">${percent(c.savingPercent)}</span></td></tr>`;}).join('')}</tbody></table></div></section>`;
}

function openDialog(d){lastFocus=document.activeElement;dialog=d;renderOverlay();}
function syncDialogFocus(){
 if(!dialog||!overlay.firstElementChild)return;
 if(!el.inert&&!overlay.contains(document.activeElement))lastFocus=document.activeElement;
 el.inert=true;document.body.style.overflow='hidden';
 if(!overlay.contains(document.activeElement)){const panel=overlay.querySelector('[role="dialog"]');panel?.setAttribute('tabindex','-1');panel?.focus({preventScroll:true});}
}

function closeDialog(){
 const layer=overlay.firstElementChild,focus=lastFocus;dialog=null;
 if(!layer){el.inert=false;document.body.style.overflow='';return;}
 const clean=()=>{if(overlay.firstElementChild===layer){overlay.innerHTML='';el.inert=false;document.body.style.overflow='';if(focus?.isConnected)focus.focus({preventScroll:true});else $('#main')?.focus({preventScroll:true});}};
 layer.setAttribute('data-closing','true');const animation=exitLayer(layer);if(animation)animation.then(clean);else clean();
}

function openOffer(id,qty,baselinePrice){const o=offerById(id);if(!o)return;detailTab='terms';openDialog({type:'offer',id,baselinePrice,quantity:qty||orderFor(id)?.quantity||o.quantity,consent:false});}
function renderOverlay(){if(!dialog)return;const d=dialog;if(d.type==='offer'){renderOfferOverlay();syncDialogFocus();return;}if(d.type==='order'){renderOrderOverlay();syncDialogFocus();return;}
 const templates={help:helpModal,privacy:privacyModal,upload:uploadModal,'new-need':needModal,notifications:notificationsModal,profile:profileModal,company:companyModal,success:successModal,review:reviewModal};const fn=templates[d.type];if(fn)overlay.innerHTML=fn();setupUpload();syncDialogFocus();}
function modal(title,body,footer='',cls=''){return `<div class="modal-wrap" data-backdrop="true"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;}
function renderOfferOverlay(){const d=dialog,o={...offerById(d.id),...(d.baselinePrice?{price:d.baselinePrice}:{})},c=calculate(o,d.quantity),joined=orderFor(o.id);
 const markup=`<div class="overlay" data-backdrop="true"><section class="drawer" data-offer-id="${d.id}" role="dialog" aria-modal="true" aria-labelledby="detail-title"><header class="drawer-header"><div><div class="eyebrow">Совместная закупка</div><h2 id="detail-title">Предложение поставщика</h2></div><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></header><div class="drawer-scroll"><div class="drawer-product"><div class="drawer-product-art" style="--visual:${o.accent}">${product(o.kind)}</div><div><h2>${o.name}</h2><p>${o.spec}</p><div class="mini-supplier">${icon('shield')}${o.supplier} · Демопредложение</div></div></div><nav class="subtabs" aria-label="Детали предложения">${[['terms','Условия'],['group','Состав группы'],['calculation','Расчёт выгоды']].map(([id,label])=>`<button class="${detailTab===id?'active':''}" data-action="detail-tab" data-tab="${id}">${label}</button>`).join('')}</nav>${detailTab==='terms'?`<p class="detail-description">${o.description}</p><label class="form-label" for="quantity">Ваш объём закупки</label><div class="quantity-line"><div class="quantity-control"><button data-action="quantity-down" aria-label="Уменьшить количество">${icon('minus','sm')}</button><input id="quantity" type="number" min="1" max="1000000" step="${o.step}" value="${esc(d.quantityInput??d.quantity)}" aria-label="Количество товара" aria-invalid="${d.quantityValid===false}" aria-describedby="detail-quantity-error"><button data-action="quantity-up" aria-label="Увеличить количество">${icon('plus','sm')}</button></div><small>${o.unit}<br>Шаг ${o.step} ${o.unit}</small></div><p id="detail-quantity-error" class="quantity-error" ${d.quantityValid===false?'':'hidden'}>Укажите целое число от 1 до 1 000 000.</p><div id="detail-calculation">${priceSummary(o,c)}</div><div class="group-block" id="detail-group">${groupSummary(o,c)}</div><div class="info-row">${icon('clock')}<div><strong>Сбор заявок до ${date(o.deadline)}</strong>Плановая поставка ${date(o.deliveryDate)}. Срок включён в условия предложения.</div></div><div class="info-row">${icon('file')}<div><strong>Отдельный заказ для вашей компании</strong>Поставщик учитывает общий объём, документы и платёж остаются отдельными.</div></div><div class="info-row">${icon('shield')}<div><strong>Правила закупки</strong>Условия зафиксированы в версии 1. При изменении цены или объёма потребуется повторное подтверждение.</div></div>`:detailTab==='group'?groupDetail(o,c):calculationDetail(o,c)}${joined?`<div class="callout">${icon('check')}Вы уже участвуете в этой закупке. Условия вашей заявки доступны в разделе «Мои закупки».</div>`:`<label class="check-label"><input type="checkbox" id="consent" ${d.consent?'checked':''}>Подтверждаю товар, количество и условия участия. При изменении итоговой стоимости я получу обновлённое предложение.</label>`}</div><footer class="drawer-footer">${button(joined?'Открыть мою заявку':c.beneficial?'Проверить и подтвердить':'Участие невыгодно',joined?'open-existing':'review','primary full',(!joined&&(!d.consent||d.quantityValid===false||!c.beneficial)?'disabled':'')+` data-id="${o.id}"`)}<p>Подтверждение создаёт демонстрационную заявку. Деньги не списываются.</p></footer></section></div>`;
 const existing=overlay.querySelector(`.overlay:not([data-closing]) .drawer[data-offer-id="${d.id}"]`);
 if(existing){const template=document.createElement('template');template.innerHTML=markup;existing.replaceChildren(...template.content.querySelector('.drawer').childNodes);existing.querySelector(`[data-tab="${detailTab}"]`)?.focus({preventScroll:true});enter(existing.querySelector('.drawer-scroll'),4,150);}
 else overlay.innerHTML=markup;
}

function priceSummary(o,c){return `<div class="price-summary"><div class="summary-row"><span>Товар в общей закупке</span><strong class="amount">${money(c.groupGoods)}</strong></div><div class="summary-row"><span>Доставка для вашей компании</span><strong class="amount">${money(o.groupDelivery)}</strong></div><div class="summary-row total"><span>Итого для вас</span><strong class="amount">${money(c.groupTotal)}</strong></div><div class="summary-row ${c.beneficial?'green':'warning'}"><span>${c.beneficial?'Экономия с доставкой':'Разница с самостоятельной закупкой'}</span><strong class="amount">${money(c.saving)} · ${percent(c.savingPercent)}</strong></div></div>`;}
function groupSummary(o,c){return `<div class="group-head"><span>${icon('users')} Объём общей закупки</span><strong>${number(c.totalQuantity)} / ${number(o.threshold)} ${o.unit}</strong></div><div class="progress ${c.ready?'ready':''}"><i style="width:${c.progress}%"></i></div><small>${c.ready?'Необходимый объём набран с учётом вашей заявки.':'До оптового объёма осталось '+number(c.missing)+' '+o.unit+' Условия действуют после набора группы.'}</small>`;}
function groupDetail(o,c){return `<div class="group-block">${groupSummary(o,c)}</div><p class="detail-description">Участники объединяют объём. Контактные и банковские данные других компаний не раскрываются.</p>${Array.from({length:Math.min(o.participants,5)},(_,i)=>`<div class="participant"><span class="participant-avatar">${['А','Б','В','Г','Д'][i]}</span><div class="participant-info">Участник ${i+1}<small>Москва и область · Подтверждено</small></div><span class="participant-qty">${number(Math.floor(o.otherQuantity/o.participants)+(i<o.otherQuantity%o.participants?1:0))} ${o.unit}</span></div>`).join('')}${o.participants>5?`<p class="analytics-note">Ещё ${o.participants-5} участников. Общий подтверждённый объём других компаний: ${number(o.otherQuantity)} ${o.unit}</p>`:''}<div class="participant"><span class="participant-avatar" style="background:#e5f0ff;color:var(--blue)">С</span><div class="participant-info">Ваша компания<small>${esc(COMPANY.name)}</small></div><span class="participant-qty">${number(c.quantity)} ${o.unit}</span></div><div class="callout">${icon('info')}После закрытия сбора поставщик подтверждает готовность исполнить закупку. Изменение значимых условий потребует нового согласия участников.</div>`;}
function calculationDetail(o,c){return `<p class="detail-description">Сравниваем одинаковый товар и одинаковое количество. Обе цены включают НДС по условиям демонстрационного предложения.</p><table class="calculation-table"><thead><tr><th>Стоимость</th><th>Самостоятельно</th><th>В группе</th></tr></thead><tbody><tr><td>Цена за ${o.unit}</td><td>${money(o.price)}</td><td>${money(o.groupPrice)}</td></tr><tr><td>Товар, ${number(c.quantity)} ${o.unit}</td><td>${money(c.standaloneGoods)}</td><td>${money(c.groupGoods)}</td></tr><tr><td>Доставка</td><td>${money(o.delivery)}</td><td>${money(o.groupDelivery)}</td></tr><tr><td>Итого</td><td>${money(c.standaloneTotal)}</td><td>${money(c.groupTotal)}</td></tr></tbody></table><div class="price-summary"><div class="summary-row green"><span>Ваша чистая экономия</span><strong>${money(c.saving)} (${percent(c.savingPercent)})</strong></div></div><div class="callout">${icon('info')}Дополнительной комиссии покупателю в этом сценарии нет. Возможное вознаграждение банку учитывается поставщиком в своём предложении и не прибавляется к итогу скрытым платежом.</div><p class="analytics-note">Расчёт действует при наборе минимального объёма группы. Стоимость хранения, финансирования и ожидания здесь не учитывается: для пилота эти расходы нужно согласовать отдельно.</p>`;}
function reviewModal(){const o={...offerById(dialog.id),...(dialog.baselinePrice?{price:dialog.baselinePrice}:{})},c=calculate(o,dialog.quantity);return modal('Подтверждение участия',`<p class="modal-desc">Проверьте условия перед созданием заявки. Общий объём не меняет ваш индивидуальный заказ.</p><div class="attachment-row mb20">${icon('box')}<div><p>${o.name}</p><small>${o.spec}</small></div><strong>${number(c.quantity)} ${o.unit}</strong></div>${priceSummary(o,c)}<div class="menu-row"><span>Поставщик</span><strong>${o.supplier}</strong></div><div class="menu-row"><span>Плановая поставка</span><strong>${date(o.deliveryDate)}</strong></div><div class="menu-row"><span>Версия условий</span><strong>1</strong></div>${!c.ready?`<div class="callout warning">${icon('clock')}Группа ещё собирается. Цена действует при достижении ${number(o.threshold)} ${o.unit} до ${date(o.deadline)}.</div>`:''}<div class="callout">${icon('shield')}В деморежиме подтверждение сохраняется в браузере. Банковская подпись и списание не выполняются.</div>`,button('Назад','back-offer','secondary')+button('Подтвердить участие','confirm','primary'));}
function successModal(){const o=offerById(dialog.id),order=state.orders.find(x=>x.id===dialog.orderId);return modal('',`<div class="success-body"><div class="success-art">${icon('check')}</div><div class="success-order">${order.number}</div><h2>Вы в закупке</h2><p>Заявка на ${number(order.quantity)} ${o.unit} добавлена. Условия и расчёт доступны в разделе «Мои закупки».</p><div class="price-summary"><div class="summary-row"><span>Стоимость вашей закупки</span><strong>${money(order.calculation.groupTotal)}</strong></div><div class="summary-row green"><span>Ожидаемая экономия</span><strong>${money(order.calculation.saving)}</strong></div></div></div>`,button('К предложениям','success-offers','secondary')+button('Мои закупки','success-orders','primary'));}
function helpModal(){return modal('Как работает Оптима',`<p class="modal-desc">Условия крупной закупки, даже если вам нужна небольшая партия.</p><div class="help-steps">${[['Укажите, что нужно бизнесу','Добавьте товар вручную или загрузите список закупок. Подбор учитывает характеристики и срок.'],['Выберите общую закупку','Сравните полную стоимость, необходимый объём и предложение поставщика.'],['Подтвердите свой заказ','Вы покупаете только нужное количество. При изменении условий сервис запросит подтверждение заново.'],['Следите за состоянием группы','После набора объёма поставщик подтверждает исполнение. В текущем прототипе показан этап согласования.']].map(([t,b],i)=>`<div class="help-step"><span class="step-number">${i+1}</span><div><h3>${t}</h3><p>${b}</p></div></div>`).join('')}</div>`,button('Понятно','close','primary'));}
function privacyModal(){return modal('Данные и условия',`<p class="modal-desc">«Оптима» является прототипом команды для Академии Финтеха. Это концепция интеграции в ВТБ, а не действующий банковский сервис.</p><div class="help-steps"><div class="info-row">${icon('shield')}<div><strong>Демонстрационные данные</strong>Компания, поставщики, цены и заявки вымышлены. Реальных списаний и юридически значимых подписей нет.</div></div><div class="info-row">${icon('file')}<div><strong>Файлы обрабатываются локально</strong>CSV и JSON читаются в браузере. Не загружайте реальные конфиденциальные документы в демонстрацию.</div></div><div class="info-row">${icon('users')}<div><strong>Банковская интеграция</strong>В будущем подключаются разрешённые данные клиентов с их согласием. Платежи содержат суммы и контрагентов, документы уточняют товары и количество.</div></div><div class="info-row">${icon('settings')}<div><strong>Состояние сохраняется на устройстве</strong>Избранное, потребности и заявки хранятся в localStorage. Их можно сбросить для нового показа.</div></div></div>`,button('Сбросить демоданные','reset-ask','tertiary')+button('Понятно','close','primary'));}
function needModal(){return modal('Новая потребность',`<p class="modal-desc">Укажите товар и необходимый объём. Точное описание поможет найти совместимую закупку.</p><form id="need-form"><div class="field"><label for="need-product">Товар</label><select id="need-product" class="input" name="product"><option value="">Выберите или укажите свой</option>${OFFERS.map(o=>`<option value="${o.id}">${o.name}</option>`).join('')}<option value="custom">Другой товар</option></select></div><div class="field"><label for="need-name">Название товара</label><input class="input" id="need-name" name="name" required placeholder="Например, курьерские пакеты" maxlength="120"></div><div class="field"><label for="need-spec">Характеристики</label><input class="input" id="need-spec" name="spec" required placeholder="Размер, материал, упаковка" maxlength="200"></div><div class="field-grid"><div class="field"><label for="need-quantity">Количество</label><input class="input" id="need-quantity" name="quantity" type="number" min="1" max="1000000" required placeholder="1 000"></div><div class="field"><label for="need-unit">Единица измерения</label><select class="input" id="need-unit" name="unit"><option>шт.</option><option>пач.</option><option>уп.</option><option>рул.</option><option>кг</option></select></div><div class="field"><label for="need-price">Текущая цена за единицу, ₽</label><input class="input" id="need-price" name="price" type="number" min="0.01" step="0.01" required placeholder="3,40"></div><div class="field"><label for="need-deadline">Нужно получить до</label><input class="input" id="need-deadline" name="deadline" type="date" min="2026-10-17" required value="2026-10-29"></div></div><div id="form-error" role="alert"></div></form>`,button('Отмена','close','secondary')+`<button class="btn primary" type="submit" form="need-form">Добавить потребность</button>`);}
function uploadModal(){if(dialog.rows)return modal('Проверка позиций',`<p class="modal-desc">Распознано позиций: ${dialog.rows.length}. Проверьте товары перед добавлением в потребности.</p><div class="file-preview"><table class="data-table"><thead><tr><th>Товар</th><th>Объём</th><th>Цена</th></tr></thead><tbody>${dialog.rows.map(r=>`<tr><td>${esc(r.name)}<div class="cell-sub">${esc(r.spec)}</div></td><td>${number(r.quantity)} ${esc(r.unit)}</td><td>${money(r.price)}</td></tr>`).join('')}</tbody></table></div><div class="callout">${icon('shield')}Данные файла не отправляются в банк или на сервер.</div>`,button('Другой файл','upload','secondary')+button('Добавить позиции','import-needs','primary'));
 return modal('Загрузка закупочных позиций',`<p class="modal-desc">Загрузите выгрузку из учётной системы в CSV или JSON. PDF и изображения можно будет подключить после интеграции распознавания документов.</p><label class="upload-area" id="dropzone" for="file-input">${icon('upload')}<strong>Перетащите файл или выберите на устройстве</strong><small>CSV или JSON, до 1 МБ</small><input type="file" class="file-input" id="file-input" accept=".csv,.json,text/csv,application/json"></label><div class="upload-choice"><button class="text-button" data-action="sample">${icon('download','sm')}Скачать пример CSV</button><button class="text-button" data-action="new-need">Ввести вручную</button></div><div id="upload-error" role="alert"></div><div class="callout">${icon('info')}Поля файла: name, spec, quantity, unit, price, deadline. Названия колонок также доступны в примере.</div>`);}
function notificationsModal(){return modal('Уведомления',`<div class="notification-item">${icon('box')}<div><p>Для вашей компании доступны ${OFFERS.length} предложений совместных закупок.</p><small>Демонстрационное уведомление</small></div></div>${state.events.length?state.events.slice(0,8).map(e=>`<div class="notification-item">${icon('check')}<div><p>${esc(e.message)}</p><small>${new Date(e.at).toLocaleString('ru-RU')}</small></div></div>`).join(''):`<div class="notification-item">${icon('shield')}<div><p>Действия по заявкам будут появляться здесь.</p><small>Журнал событий</small></div></div>`}`,button('Понятно','close','primary'));}
function profileModal(){return modal('Профиль',`<div class="row-between mb20"><div class="user-avatar" style="width:48px;height:48px;font-size:16px">АС</div><span class="tour-tag">Демонстрационный профиль</span></div><div class="menu-row"><span>Пользователь</span><strong>${COMPANY.owner}</strong></div><div class="menu-row"><span>Компания</span><strong>${esc(COMPANY.name)}</strong></div><div class="menu-row"><span>Роль</span><strong>Руководитель</strong></div><div class="menu-row"><span>Регион закупок</span><strong>${COMPANY.region}</strong></div>`,button('Закрыть','close','primary'));}
function companyModal(){return modal('Ваша компания',`<div class="attachment-row">${icon('briefcase')}<div><p>${esc(COMPANY.name)}</p><small>${COMPANY.region}</small></div><span class="status blue">Демоданные</span></div><p class="modal-desc mt16">Для демонстрации выбрана тестовая компания. Её заявки и потребности сохраняются в этом браузере. Реальные данные компании не используются.</p>`,button('Понятно','close','primary'));}
function renderOrderOverlay(){const order=state.orders.find(o=>o.id===dialog.id),o=offerById(order.offerId);overlay.innerHTML=`<div class="overlay" data-backdrop="true"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="detail-title"><header class="drawer-header"><div><div class="eyebrow">${order.number}</div><h2 id="detail-title">Ваша закупка</h2></div><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></header><div class="drawer-scroll"><div class="drawer-product"><div class="drawer-product-art" style="--visual:${o.accent}">${product(o.kind)}</div><div><h2>${o.name}</h2><p>${number(order.quantity)} ${o.unit} · ${o.supplier}</p><div class="mt16"><span class="status ${order.status==='cancelled'?'gray':order.status==='ready'?'green':'blue'}">${statusLabel(order)}</span></div></div></div>${priceSummary(o,order.calculation)}<div class="detail-label">Согласованные условия</div><div class="menu-row"><span>Плановая поставка</span><strong>${date(o.deliveryDate)}</strong></div><div class="menu-row"><span>Версия условий</span><strong>${order.version}</strong></div><div class="menu-row"><span>Ваши документы и платёж</span><span>Отдельно от других участников</span></div><div class="order-timeline"><div class="timeline-item"><span class="timeline-dot">${icon('check')}</span><div><strong>Заявка создана</strong>${new Date(order.createdAt).toLocaleString('ru-RU')}</div></div><div class="timeline-item"><span class="timeline-dot">${icon('check')}</span><div><strong>Условия версии ${order.version} подтверждены</strong>Сохранены количество, стоимость и согласие участника</div></div><div class="timeline-item"><span class="timeline-dot">${icon(order.status==='cancelled'?'close':'clock')}</span><div><strong>${order.status==='cancelled'?'Участие отменено':order.status==='ready'?'Объём группы набран':'Ожидание набора группы'}</strong>${order.status==='cancelled'?'Деньги не списывались':'Следующий этап: подтверждение поставщика'}</div></div></div><div class="callout">${icon('info')}Документооборот, банковские платежи и отслеживание доставки пока не подключены. Заявка моделирует согласование участия.</div></div><footer class="drawer-footer">${button(icon('download','sm')+'Выгрузить условия','download-order','secondary full',`data-id="${order.id}"`)}${order.status!=='cancelled'?`<button class="text-button" data-action="cancel-ask" data-id="${order.id}" style="width:100%;justify-content:center;margin-top:8px;color:#965b61">Отменить участие</button>`:''}</footer></section></div>`;}
function toast(message){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast">${icon('check')}<span>${esc(message)}</span></div>`;toastTimer=setTimeout(()=>{const root=$('#toast-root');if(root)root.innerHTML='';},3600);}
function switchView(v){view=v;closeDialog();render();if(!el.inert&&!el.contains(document.activeElement))$('#main')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function refreshOffers(animate=true){
 if(!$('#offers-grid'))return;
 const before=selectedOfferId;ensureSelection();
 $('#offers-grid').innerHTML=offerCards();$('#offers-count').textContent=filtered().length;
 const panel=$('#purchase-preview');if(panel.dataset.offerId!==(selectedOfferId||'')){panel.innerHTML=quoteView();panel.dataset.offerId=selectedOfferId||'';}
 const matched=matchedIds(),counts={all:OFFERS.length,matched:matched.size,favorites:state.favorites.length};
 for(const b of document.querySelectorAll('[data-action="scope"]')){b.classList.toggle('active',b.dataset.scope===scope);b.setAttribute('aria-pressed',String(b.dataset.scope===scope));b.querySelector('[data-scope-count]').textContent=counts[b.dataset.scope];}
 if($('#category'))$('#category').value=category;if($('#sort'))$('#sort').value=sort;if($('#offer-search'))$('#offer-search').value=query;
 fitQuotePanel();
 if(animate&&before!==selectedOfferId)enter($('#purchase-preview .quote-scroll'),6,200);
 updateShell();
}

function updateQuantity(q){
 if(!dialog||dialog.type!=='offer')return;
 const o={...offerById(dialog.id),...(dialog.baselinePrice?{price:dialog.baselinePrice}:{})};
 dialog.quantityValid=true;dialog.quantity=Math.max(1,Math.min(1000000,Math.round(q)||1));dialog.quantityInput=String(dialog.quantity);
 const c=calculate(o,dialog.quantity),input=$('#quantity');
 if(input){input.value=dialog.quantity;input.setAttribute('aria-invalid','false');}
 if($('#detail-quantity-error'))$('#detail-quantity-error').hidden=true;
 if($('#detail-calculation'))$('#detail-calculation').innerHTML=priceSummary(o,c);
 if($('#detail-group'))$('#detail-group').innerHTML=groupSummary(o,c);
 const b=overlay.querySelector('[data-action="review"]');if(b)b.disabled=!dialog.consent||!c.beneficial;
}
function updateDetailInput(input){
 if(dialog?.type!=='offer')return;
 dialog.quantityInput=input.value;
 dialog.quantityValid=input.value!==''&&Number.isInteger(Number(input.value))&&Number(input.value)>0&&Number(input.value)<=1000000;
 if(dialog.quantityValid){updateQuantity(Number(input.value));return;}
 input.setAttribute('aria-invalid','true');
 if($('#detail-quantity-error'))$('#detail-quantity-error').hidden=false;
 const b=overlay.querySelector('[data-action="review"]');if(b)b.disabled=true;
}
function download(text,name,type='text/plain'){const a=document.createElement('a');const u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function exportCsv(){const head='Товар;Количество;Самостоятельно;В группе;Экономия;Экономия, %\n';const rows=OFFERS.map(o=>{const c=calculate(o);return [o.name,o.quantity,c.standaloneTotal,c.groupTotal,c.saving,c.savingPercent.toFixed(2)].join(';');}).join('\n');download('\uFEFF'+head+rows,'optima-calculation.csv','text/csv;charset=utf-8');toast('Расчёт подготовлен к скачиванию');}
function sampleCsv(){download('\uFEFFname;spec;quantity;unit;price;deadline\nКурьерские пакеты;250 × 350 мм, 50 мкм;1000;шт.;3.4;2026-10-26\nБумага для офиса;А4, 80 г/м², 500 листов;10;пач.;440;2026-10-28','optima-needs-example.csv','text/csv;charset=utf-8');}
async function readFile(file){if(!file)return;try{if(file.size>1024*1024)throw new Error('Максимальный размер файла — 1 МБ');if(!/\.(csv|json)$/i.test(file.name))throw new Error('Выберите CSV или JSON');const rows=parseNeeds(await file.text(),file.name);dialog={type:'upload',rows};renderOverlay();}catch(e){$('#upload-error').innerHTML=`<div class="error-message">${esc(e.message)}</div>`;}}
function setupUpload(){const z=$('#dropzone');if(z){z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('dragging');});z.addEventListener('dragleave',()=>z.classList.remove('dragging'));z.addEventListener('drop',e=>{e.preventDefault();z.classList.remove('dragging');readFile(e.dataTransfer.files[0]);});$('#file-input').addEventListener('change',e=>readFile(e.target.files[0]));}}
const actions={
 'catalog-layout':b=>{const layout=b.dataset.layout==='list'?'list':'grid';state.ui={...state.ui,catalogLayout:layout};save();$('#offers-grid').dataset.layout=layout;for(const control of document.querySelectorAll('[data-action="catalog-layout"]')){const active=control.dataset.layout===layout;control.classList.toggle('active',active);control.setAttribute('aria-pressed',String(active));}fitQuotePanel();},
 'browse-offers':()=>{$('#catalog-start')?.scrollIntoView?.({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});$('#offer-search')?.focus({preventScroll:true});},
 view:b=>switchView(b.dataset.view),scope:b=>{scope=b.dataset.scope;refreshOffers();b.focus();},'clear-filter':()=>{category='Все';scope='all';query='';refreshOffers();},'select-offer':b=>selectOffer(b.dataset.id),'quote-open':()=>{if(quoteValid&&selectedOfferId)openOffer(selectedOfferId,quoteQuantity);},'quote-minus':()=>updateQuoteQuantity(Math.max(1,quoteQuantity-offerById(selectedOfferId).step)),'quote-plus':()=>updateQuoteQuantity(Math.min(1000000,quoteQuantity+offerById(selectedOfferId).step)),'go-offers':()=>switchView('offers'),
 offer:b=>openOffer(b.dataset.id,Number(b.dataset.quantity)||undefined,Number(b.dataset.price)||undefined),favorite:b=>{const id=b.dataset.id;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();refreshOffers();document.querySelector(`[data-action="favorite"][data-id="${id}"]`)?.focus({preventScroll:true});},
 close:closeDialog,help:()=>openDialog({type:'help'}),privacy:()=>openDialog({type:'privacy'}),profile:()=>openDialog({type:'profile'}),company:()=>openDialog({type:'company'}),
 notifications:()=>{state.notificationsRead=true;save();updateShell();openDialog({type:'notifications'});},
 'global-search':()=>{switchView('offers');$('#offer-search')?.focus();},'new-need':()=>openDialog({type:'new-need'}),upload:()=>openDialog({type:'upload'}),sample:sampleCsv,export:exportCsv,
 'detail-tab':b=>{detailTab=b.dataset.tab;renderOfferOverlay();},'quantity-down':()=>updateQuantity(dialog.quantity-offerById(dialog.id).step),'quantity-up':()=>updateQuantity(dialog.quantity+offerById(dialog.id).step),
 review:()=>{if(!dialog.consent||dialog.quantityValid===false)return;dialog={...dialog,type:'review'};renderOverlay();},'back-offer':()=>{dialog={...dialog,type:'offer'};renderOverlay();},
 confirm:()=>{const d=dialog,o={...offerById(d.id),...(d.baselinePrice?{price:d.baselinePrice}:{})};if(orderFor(o.id)){toast('Вы уже участвуете в закупке');return;}const calculation=calculate(o,d.quantity);if(!calculation.beneficial)return;const order={id:crypto.randomUUID(),number:'ЗК-'+String(1001+state.orders.length),offerId:o.id,quantity:d.quantity,calculation,version:1,status:calculation.ready?'ready':'collecting',createdAt:new Date().toISOString()};state.orders.unshift(order);addEvent(state,`Создана заявка ${order.number}: ${o.name}`);save();render();dialog={type:'success',id:o.id,orderId:order.id};renderOverlay();},
 'open-existing':b=>{const o=orderFor(b.dataset.id);if(o){dialog={type:'order',id:o.id};renderOverlay();}},'order-detail':b=>openDialog({type:'order',id:b.dataset.id}),
 'success-offers':()=>switchView('offers'),'success-orders':()=>switchView('orders'),'order-filter':b=>{orderFilter=b.dataset.filter;render();},
 'delete-need':b=>{const n=state.needs.find(n=>n.id===b.dataset.id);dialog={type:'delete-need',id:n.id};overlay.innerHTML=modal('Удалить потребность?',`<p class="modal-desc">${esc(n.name)} будет удалён из списка. Это не отменяет уже созданную заявку на закупку.</p>`,button('Оставить','close','secondary')+button('Удалить','delete-need-confirm','danger'));document.body.style.overflow='hidden';},
 'delete-need-confirm':()=>{state.needs=state.needs.filter(n=>n.id!==dialog.id);save();closeDialog();render();toast('Потребность удалена');},
 'import-needs':()=>{const rows=dialog.rows;rows.forEach(row=>state.needs.push({...row,id:crypto.randomUUID(),source:'Загружено из файла'}));addEvent(state,`Загружено потребностей: ${rows.length}`);save();switchView('needs');toast(`Добавлено позиций: ${rows.length}`);},
 'download-order':b=>{const order=state.orders.find(o=>o.id===b.dataset.id),o=offerById(order.offerId);download(JSON.stringify({demo:true,company:COMPANY.name,product:o.name,specification:o.spec,supplier:o.supplier,deliveryDate:o.deliveryDate,...order},null,2),`optima-${order.number}.json`,'application/json');toast('Условия заявки подготовлены');},
 'cancel-ask':b=>{dialog={type:'cancel',id:b.dataset.id};overlay.innerHTML=modal('Отменить участие?',`<p class="modal-desc">Ваша заявка перестанет участвовать в сборе группы. При повторном присоединении потребуется заново подтвердить актуальные условия.</p><div class="callout">${icon('info')}В демонстрации деньги не списывались. В реальной системе последствия отказа определяются согласованными условиями.</div>`,button('Сохранить участие','close','secondary')+button('Отменить участие','cancel-confirm','danger'));},
 'cancel-confirm':()=>{const order=state.orders.find(o=>o.id===dialog.id);order.status='cancelled';addEvent(state,`Участие в закупке ${order.number} отменено`);save();switchView('orders');toast('Участие отменено. Деньги не списывались');},
 'reset-ask':()=>{dialog={type:'reset'};overlay.innerHTML=modal('Сбросить демонстрацию?',`<p class="modal-desc">Сохранённые в этом браузере заявки, избранное и загруженные позиции будут удалены. Начальные примеры появятся заново.</p>`,button('Отмена','close','secondary')+button('Сбросить','reset-confirm','danger'));},
 'reset-confirm':()=>{localStorage.removeItem('optima-vtb-state-v1');state=loadState();category='Все';scope='all';query='';selectedOfferId=null;switchView('offers');toast('Демонстрация сброшена');}
};
document.addEventListener('click',e=>{if(e.target.matches('[data-backdrop]')){closeDialog();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const f=actions[b.dataset.action];if(f){f(b);syncDialogFocus();}});
document.addEventListener('input',e=>{if(e.target.id==='offer-search'){query=e.target.value;refreshOffers();}if(e.target.id==='quote-quantity')updateQuoteQuantity(e.target.value);if(e.target.id==='quantity')updateDetailInput(e.target);});
document.addEventListener('change',e=>{if(e.target.id==='category'){category=e.target.value;refreshOffers();}if(e.target.id==='sort'){sort=e.target.value;refreshOffers();}if(e.target.id==='consent'&&dialog?.type==='offer'){dialog.consent=e.target.checked;const b=overlay.querySelector('[data-action="review"]');if(b)b.disabled=!dialog.consent||dialog.quantityValid===false||!calculate({...offerById(dialog.id),...(dialog.baselinePrice?{price:dialog.baselinePrice}:{})},dialog.quantity).beneficial;}
 if(e.target.id==='need-product'){const o=offerById(e.target.value);if(o){$('#need-name').value=o.name;$('#need-spec').value=o.spec;$('#need-quantity').value=o.quantity;$('#need-unit').value=o.unit;$('#need-price').value=o.price;$('#need-deadline').value=o.deliveryDate;}}
});
document.addEventListener('submit',e=>{if(e.target.id!=='need-form')return;e.preventDefault();const row=Object.fromEntries(new FormData(e.target));row.quantity=Number(row.quantity);row.price=Number(row.price);const errors=validateNeed(row);if(errors.length){$('#form-error').innerHTML=`<div class="error-message">${errors.map(esc).join('<br>')}</div>`;return;}state.needs.push({...row,id:crypto.randomUUID(),source:'Добавлено вручную'});addEvent(state,`Добавлена потребность: ${row.name}`);save();switchView('needs');toast(matchNeed(row,OFFERS)?'Потребность добавлена. Подобрано предложение':'Потребность добавлена. Ищем совместимое предложение');});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!dialog&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.target.closest?.('input,textarea,select,[contenteditable]')){e.preventDefault();switchView('offers');$('#offer-search')?.focus();return;}if(e.key==='Escape'&&dialog){closeDialog();return;}if(e.key==='Tab'&&dialog){const f=[...overlay.querySelectorAll('button:not([disabled]),input:not([disabled]),select,a[href],textarea')].filter(x=>x.offsetParent!==null);if(!f.length)return;const first=f[0],last=f.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===overlay.querySelector('[role="dialog"]'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['offers','orders','needs','analytics'].includes(v)&&v!==view)switchView(v);});
const initialView=location.hash.slice(1);if(['offers','orders','needs','analytics'].includes(initialView))view=initialView;
render();
